-- =====================================================================
-- Módulo 4 · Workout Builder (parte 1): biblioteca de ejercicios.
-- Pegar entero en Supabase → SQL Editor → Run (después del 006). Una sola vez.
-- Carga 465 ejercicios en Casademont Zaragoza (links a los shorts del canal
-- «Sebastian Martinez - Kinesiologia Deportiva»; la app solo guarda el link).
-- =====================================================================

create table public.ejercicios (
  id uuid primary key default gen_random_uuid(),
  club_id uuid not null references public.clubs(id) on delete cascade,
  nombre text not null check (length(btrim(nombre)) between 1 and 120),
  categoria text check (categoria is null or length(categoria) <= 60),
  implemento text check (implemento is null or length(implemento) <= 60),
  lateralidad text check (lateralidad in ('Unilateral', 'Bilateral')),
  contraccion text check (contraccion in ('Isométrico', 'Excéntrico')),
  video_url text check (video_url is null or video_url ~ '^https://'),
  consignas text check (consignas is null or length(consignas) <= 2000),
  creado_por uuid references public.perfiles(id),
  creado_en timestamptz not null default now(),
  actualizado_en timestamptz not null default now(),
  eliminado_en timestamptz
);
create unique index ejercicios_nombre_unico on public.ejercicios (club_id, lower(btrim(nombre))) where eliminado_en is null;
create index ejercicios_club on public.ejercicios (club_id) where eliminado_en is null;

alter table public.ejercicios enable row level security;
-- Lo ve todo el club que tenga acceso al Workout Builder (los jugadores también, para ver sus ejercicios).
create policy ejercicios_ver on public.ejercicios for select
  using (club_id = public.mi_club() and public.nivel_de(auth.uid(), 'workout_builder') <> 'sin');

create or replace function public.guardar_ejercicio(p_id uuid, p jsonb) returns uuid
language plpgsql security definer set search_path = public as $$
declare
  v_club uuid := mi_club(); v_id uuid; v_nombre text := btrim(coalesce(p ->> 'nombre', ''));
  v_video text := nullif(btrim(coalesce(p ->> 'video_url', '')), ''); v_antes text;
begin
  if v_club is null or nivel_de(auth.uid(), 'workout_builder') <> 'editar' then
    raise exception 'Solo quien edita el Workout Builder puede cambiar la biblioteca.';
  end if;
  if v_nombre = '' then raise exception 'El ejercicio necesita un nombre.'; end if;
  if v_video is not null and v_video !~ '^https://' then raise exception 'El video tiene que ser un link que empiece con https://'; end if;
  if exists (select 1 from ejercicios where club_id = v_club and eliminado_en is null
             and lower(btrim(nombre)) = lower(v_nombre) and id is distinct from p_id) then
    raise exception 'Ya hay un ejercicio que se llama «%».', v_nombre;
  end if;

  if p_id is null then
    insert into ejercicios (club_id, nombre, categoria, implemento, lateralidad, contraccion, video_url, consignas, creado_por)
    values (v_club, v_nombre, nullif(btrim(p ->> 'categoria'), ''), nullif(btrim(p ->> 'implemento'), ''),
            nullif(p ->> 'lateralidad', ''), nullif(p ->> 'contraccion', ''), v_video, nullif(btrim(p ->> 'consignas'), ''), auth.uid())
    returning id into v_id;
    perform _registrar(v_club, 'creó el ejercicio «' || v_nombre || '».');
  else
    select nombre into v_antes from ejercicios where id = p_id and club_id = v_club and eliminado_en is null;
    if v_antes is null then raise exception 'Ese ejercicio ya no existe.'; end if;
    update ejercicios set nombre = v_nombre, categoria = nullif(btrim(p ->> 'categoria'), ''), implemento = nullif(btrim(p ->> 'implemento'), ''),
           lateralidad = nullif(p ->> 'lateralidad', ''), contraccion = nullif(p ->> 'contraccion', ''), video_url = v_video,
           consignas = nullif(btrim(p ->> 'consignas'), ''), actualizado_en = now()
    where id = p_id;
    v_id := p_id;
    perform _registrar(v_club, 'editó el ejercicio «' || v_nombre || '»' || case when v_antes <> v_nombre then ' (antes «' || v_antes || '»)' else '' end || '.');
  end if;
  return v_id;
end $$;

-- Se oculta de la biblioteca; lo ya programado en sesiones lo sigue mostrando.
create or replace function public.eliminar_ejercicio(p_id uuid) returns void
language plpgsql security definer set search_path = public as $$
declare v_club uuid := mi_club(); v_nombre text;
begin
  if v_club is null or nivel_de(auth.uid(), 'workout_builder') <> 'editar' then
    raise exception 'Solo quien edita el Workout Builder puede cambiar la biblioteca.';
  end if;
  update ejercicios set eliminado_en = now() where id = p_id and club_id = v_club and eliminado_en is null
  returning nombre into v_nombre;
  if v_nombre is null then raise exception 'Ese ejercicio ya no existe.'; end if;
  perform _registrar(v_club, 'eliminó el ejercicio «' || v_nombre || '».');
end $$;

revoke all on function public.guardar_ejercicio(uuid, jsonb) from public, anon;
revoke all on function public.eliminar_ejercicio(uuid) from public, anon;
grant execute on function public.guardar_ejercicio(uuid, jsonb) to authenticated;
grant execute on function public.eliminar_ejercicio(uuid) to authenticated;

-- ---------- Exportar club: con la biblioteca y las excepciones de cuestionarios ----------

create or replace function public.exportar_club() returns jsonb
language plpgsql security definer set search_path = public as $$
declare v_club uuid := mi_club(); v jsonb;
begin
  if not soy_admin() then raise exception 'Solo un administrador puede exportar los datos del club.'; end if;
  select jsonb_build_object(
    'exportado_en', now(),
    'club', (select to_jsonb(c) - 'notas_dueno' from clubs c where c.id = v_club),
    'roles', (select coalesce(jsonb_agg(to_jsonb(r)), '[]') from roles r where r.club_id = v_club),
    'personas', (select coalesce(jsonb_agg(to_jsonb(p)), '[]') from perfiles p where p.club_id = v_club),
    'grupos', (select coalesce(jsonb_agg(to_jsonb(g)), '[]') from grupos g where g.club_id = v_club),
    'grupo_miembros', (select coalesce(jsonb_agg(to_jsonb(m)), '[]') from grupo_miembros m join grupos g on g.id = m.grupo_id where g.club_id = v_club),
    'lugares', (select coalesce(jsonb_agg(to_jsonb(l)), '[]') from lugares l where l.club_id = v_club),
    'actividades', (select coalesce(jsonb_agg(to_jsonb(a)), '[]') from actividades a where a.club_id = v_club),
    'actividad_destinos', (select coalesce(jsonb_agg(to_jsonb(d)), '[]') from actividad_destinos d join actividades a on a.id = d.actividad_id where a.club_id = v_club),
    'actividad_confirmaciones', (select coalesce(jsonb_agg(to_jsonb(x)), '[]') from actividad_confirmaciones x join actividades a on a.id = x.actividad_id where a.club_id = v_club),
    'wellness', (select coalesce(jsonb_agg(to_jsonb(w)), '[]') from wellness w where w.club_id = v_club),
    'rpe', (select coalesce(jsonb_agg(to_jsonb(r)), '[]') from rpe r where r.club_id = v_club),
    'minutos_equipo', (select coalesce(jsonb_agg(to_jsonb(m)), '[]') from minutos_equipo m where m.club_id = v_club),
    'minutos_jugador', (select coalesce(jsonb_agg(to_jsonb(m)), '[]') from minutos_jugador m where m.club_id = v_club),
    'cuestionario_excepciones', (select coalesce(jsonb_agg(to_jsonb(x)), '[]') from cuestionario_excepciones x where x.club_id = v_club),
    'ejercicios', (select coalesce(jsonb_agg(to_jsonb(e)), '[]') from ejercicios e where e.club_id = v_club),
    'registro_cambios', (select coalesce(jsonb_agg(to_jsonb(x) order by x.id), '[]') from registro_cambios x where x.club_id = v_club)
  ) into v;
  perform _registrar(v_club, 'exportó todos los datos del club.');
  return v;
end $$;

